def cmul(z, w):
    a, b = z
    c, d = w
    return (a * c - b * d, a * d + b * c)


def cdiv(z, w):
    a, b = z
    c, d = w
    den = c * c + d * d
    top = cmul((a, b), (c, -d))
    return (top[0] / den, top[1] / den)

