widget.solution:
import cmath


def i_power(n):
    return [1, 1j, -1, -1j][n % 4]


def quad_roots(a, b, c):
    d = cmath.sqrt(b * b - 4 * a * c)
    return [(-b + d) / (2 * a), (-b - d) / (2 * a)]
